CREATE OR REPLACE FUNCTION private.crm_upgrade_begin(p_actor uuid, p_command text, p_key uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE r public.command_receipts; h text:=encode(sha256(convert_to(p_payload::text,'UTF8')),'hex');
BEGIN
 IF p_key IS NULL THEN RAISE EXCEPTION 'Idempotency UUID required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_actor::text||'/'||p_command||'/'||p_key::text,0));
 SELECT * INTO r FROM public.command_receipts WHERE actor_id=p_actor AND command=p_command AND idempotency_key=p_key;
 IF r.id IS NOT NULL THEN
  IF r.request_hash<>h THEN RAISE EXCEPTION 'Idempotency key reused with a different payload'; END IF;
  RETURN r.result;
 END IF;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION private.crm_upgrade_finish(p_actor uuid, p_command text, p_key uuid, p_payload jsonb, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 INSERT INTO public.command_receipts(actor_id,command,idempotency_key,request_hash,result)
 VALUES(p_actor,p_command,p_key,encode(sha256(convert_to(p_payload::text,'UTF8')),'hex'),p_result);
 INSERT INTO public.audit_logs(actor_user_id,effective_user_id,action,entity_type,entity_id,new_data)
 VALUES(p_actor,p_actor,p_command,'command',p_key,p_result);
 RETURN p_result;
END $function$
;
CREATE OR REPLACE FUNCTION private.crm_upgrade_receipt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE p public.purchase_order_items; r public.goods_receipts; q numeric; po_status text;
BEGIN
 SELECT * INTO r FROM public.goods_receipts WHERE id=NEW.goods_receipt_id;
 IF NEW.purchase_order_item_id IS NULL THEN RETURN NEW; END IF; -- preserve historical non-PO receipts
 SELECT status INTO po_status FROM public.purchase_orders WHERE id=r.purchase_order_id FOR UPDATE;
 IF po_status NOT IN ('ordered','part_received') THEN RAISE EXCEPTION 'Receipt requires an ordered active PO'; END IF;
 SELECT * INTO p FROM public.purchase_order_items WHERE id=NEW.purchase_order_item_id FOR UPDATE;
 IF p.id IS NULL OR p.purchase_order_id IS DISTINCT FROM r.purchase_order_id OR p.variant_id<>NEW.variant_id
 THEN RAISE EXCEPTION 'Receipt does not match purchase-order line'; END IF;
 IF NEW.location_id IS NOT NULL AND r.warehouse_id IS DISTINCT FROM (SELECT warehouse_id FROM public.warehouse_locations WHERE id=NEW.location_id)
 THEN RAISE EXCEPTION 'Receipt location is outside receiving warehouse'; END IF;
 SELECT coalesce(sum(quantity_received),0) INTO q FROM public.goods_receipt_items WHERE purchase_order_item_id=p.id;
 IF NEW.quantity_received<=0 OR q+NEW.quantity_received>p.quantity_ordered THEN RAISE EXCEPTION 'Receipt exceeds remaining ordered quantity'; END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION private.crm_upgrade_receive_po(p_po_id uuid, p_lines jsonb, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid; payload jsonb; old_result jsonb; po public.purchase_orders; pi public.purchase_order_items; line jsonb; rid uuid; item_id uuid; q numeric; loc uuid;
BEGIN
 u:=private.crm_upgrade_require('purchasing','update',true); PERFORM private.crm_upgrade_require('inventory','update',true);
 payload:=jsonb_build_object('po',p_po_id,'lines',p_lines);
 old_result:=private.crm_upgrade_begin(u,'receive_po',p_key,payload); IF old_result IS NOT NULL THEN RETURN old_result; END IF;
 SELECT * INTO po FROM public.purchase_orders WHERE id=p_po_id FOR UPDATE;
 IF po.id IS NULL OR po.status NOT IN ('ordered','part_received') THEN RAISE EXCEPTION 'Ordered or partially received PO required'; END IF;
 IF p_lines IS NULL OR jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines)=0 THEN RAISE EXCEPTION 'Receipt lines required'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_lines) e GROUP BY e->>'purchase_order_item_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'Duplicate receipt line'; END IF;
 INSERT INTO public.goods_receipts(purchase_order_id,warehouse_id,supplier_id,received_by,idempotency_key)
 VALUES(po.id,po.warehouse_id,po.supplier_id,u,p_key) RETURNING id INTO rid;
 FOR line IN SELECT value FROM jsonb_array_elements(p_lines) ORDER BY (SELECT variant_id FROM public.purchase_order_items WHERE id=(value->>'purchase_order_item_id')::uuid),value->>'location_id',value->>'purchase_order_item_id' LOOP
  SELECT * INTO pi FROM public.purchase_order_items WHERE id=(line->>'purchase_order_item_id')::uuid AND purchase_order_id=po.id FOR UPDATE;
  q:=(line->>'quantity')::numeric; loc:=(line->>'location_id')::uuid;
  IF pi.id IS NULL OR q IS NULL OR q<=0 OR q<>trunc(q) OR loc IS NULL OR NOT EXISTS(SELECT 1 FROM public.warehouse_locations l WHERE l.id=loc AND l.warehouse_id=po.warehouse_id AND l.active)
  THEN RAISE EXCEPTION 'Matching PO line, positive integer quantity and receiving bin required'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('crm-stock/'||pi.variant_id::text||'/'||po.warehouse_id::text||'/'||loc::text,0));
  INSERT INTO public.goods_receipt_items(goods_receipt_id,purchase_order_item_id,variant_id,quantity_received,location_id)
  VALUES(rid,pi.id,pi.variant_id,q,loc) RETURNING id INTO item_id;
  INSERT INTO public.inventory_balances(variant_id,warehouse_id,location_id,quantity_on_hand)
  VALUES(pi.variant_id,po.warehouse_id,loc,q)
  ON CONFLICT(variant_id,warehouse_id,location_id) DO UPDATE SET quantity_on_hand=public.inventory_balances.quantity_on_hand+excluded.quantity_on_hand,version=public.inventory_balances.version+1;
  INSERT INTO public.stock_movements(client_event_id,movement_type,variant_id,to_warehouse_id,to_location_id,quantity,reference_type,reference_id,goods_receipt_item_id,created_by)
  VALUES('crm-receipt/'||item_id::text,'receipt',pi.variant_id,po.warehouse_id,loc,q,'goods_receipt',rid,item_id,u);
 END LOOP;
 RETURN private.crm_upgrade_finish(u,'receive_po',p_key,payload,jsonb_build_object('goods_receipt_id',rid,'purchase_order_id',po.id));
END $function$
;
CREATE OR REPLACE FUNCTION private.crm_upgrade_refresh_receipt_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE po uuid;
BEGIN
 IF NEW.purchase_order_item_id IS NULL THEN RETURN NEW; END IF;
 UPDATE public.purchase_order_items p SET quantity_received=(SELECT coalesce(sum(g.quantity_received),0) FROM public.goods_receipt_items g WHERE g.purchase_order_item_id=p.id) WHERE p.id=NEW.purchase_order_item_id RETURNING purchase_order_id INTO po;
 UPDATE public.purchase_orders p SET status=CASE
  WHEN NOT EXISTS(SELECT 1 FROM public.purchase_order_items i WHERE i.purchase_order_id=po AND i.quantity_received<i.quantity_ordered) THEN 'received'
  WHEN EXISTS(SELECT 1 FROM public.purchase_order_items i WHERE i.purchase_order_id=po AND i.quantity_received>0) THEN 'part_received'
  ELSE p.status END WHERE p.id=po AND p.status<>'cancelled';
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION private.crm_upgrade_validate_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE j uuid; v uuid; w uuid; x record;
BEGIN
 IF TG_TABLE_NAME='request_return_links' THEN
  SELECT job_order_id INTO j FROM public.product_requests WHERE id=NEW.request_id;
  IF j IS DISTINCT FROM (SELECT job_order_id FROM public.product_returns WHERE id=NEW.product_return_id)
  THEN RAISE EXCEPTION 'Request and return must belong to the same job'; END IF;
 ELSIF TG_TABLE_NAME='job_order_items' THEN
  IF NEW.request_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO x FROM public.product_requests WHERE id=NEW.request_id;
  IF x.job_order_id<>NEW.job_order_id OR x.variant_id IS DISTINCT FROM NEW.variant_id
  THEN RAISE EXCEPTION 'Job item must match its request job and SKU'; END IF;
 ELSIF TG_TABLE_NAME='product_return_items' THEN
  IF NEW.job_order_item_id IS NULL THEN RETURN NEW; END IF;
  SELECT job_order_id,variant_id INTO j,v FROM public.job_order_items WHERE id=NEW.job_order_item_id;
  IF j IS DISTINCT FROM (SELECT job_order_id FROM public.product_returns WHERE id=NEW.product_return_id) OR v IS DISTINCT FROM NEW.variant_id
  THEN RAISE EXCEPTION 'Return item must match its job item and SKU'; END IF;
 ELSIF TG_TABLE_NAME='stock_reservations' THEN
  IF NEW.inventory_balance_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO x FROM public.inventory_balances WHERE id=NEW.inventory_balance_id;
  IF x.variant_id<>NEW.variant_id OR x.warehouse_id<>NEW.warehouse_id THEN RAISE EXCEPTION 'Reservation stock balance mismatch'; END IF;
 ELSIF TG_TABLE_NAME='tasks' THEN
  IF NEW.product_request_id IS NOT NULL AND NEW.job_order_id IS DISTINCT FROM (SELECT job_order_id FROM public.product_requests WHERE id=NEW.product_request_id)
  THEN RAISE EXCEPTION 'Task request job mismatch'; END IF;
  IF NEW.product_return_id IS NOT NULL AND NEW.job_order_id IS DISTINCT FROM (SELECT job_order_id FROM public.product_returns WHERE id=NEW.product_return_id)
  THEN RAISE EXCEPTION 'Task return job mismatch'; END IF;
 ELSIF TG_TABLE_NAME='stock_movements' THEN
  IF NEW.from_location_id IS NOT NULL AND NEW.from_warehouse_id IS DISTINCT FROM (SELECT warehouse_id FROM public.warehouse_locations WHERE id=NEW.from_location_id)
  THEN RAISE EXCEPTION 'Stock source location is outside source warehouse'; END IF;
  IF NEW.to_location_id IS NOT NULL AND NEW.to_warehouse_id IS DISTINCT FROM (SELECT warehouse_id FROM public.warehouse_locations WHERE id=NEW.to_location_id)
  THEN RAISE EXCEPTION 'Stock destination location is outside destination warehouse'; END IF;
  IF NEW.job_order_item_id IS NOT NULL AND NEW.variant_id IS DISTINCT FROM (SELECT variant_id FROM public.job_order_items WHERE id=NEW.job_order_item_id)
  THEN RAISE EXCEPTION 'Movement job item SKU mismatch'; END IF;
  IF NEW.product_request_id IS NOT NULL AND NEW.variant_id IS DISTINCT FROM (SELECT variant_id FROM public.product_requests WHERE id=NEW.product_request_id)
  THEN RAISE EXCEPTION 'Movement product request SKU mismatch'; END IF;
  IF NEW.product_return_item_id IS NOT NULL AND NEW.variant_id IS DISTINCT FROM (SELECT variant_id FROM public.product_return_items WHERE id=NEW.product_return_item_id)
  THEN RAISE EXCEPTION 'Movement return item SKU mismatch'; END IF;
  IF NEW.goods_receipt_item_id IS NOT NULL AND NEW.variant_id IS DISTINCT FROM (SELECT variant_id FROM public.goods_receipt_items WHERE id=NEW.goods_receipt_item_id)
  THEN RAISE EXCEPTION 'Movement receipt item SKU mismatch'; END IF;
 ELSIF TG_TABLE_NAME='job_settlements' THEN
  IF NEW.invoice_id IS NOT NULL AND NEW.job_order_id IS DISTINCT FROM (SELECT job_order_id FROM public.invoices WHERE id=NEW.invoice_id)
  THEN RAISE EXCEPTION 'Settlement invoice job mismatch'; END IF;
  IF NEW.credit_note_id IS NOT NULL AND NEW.job_order_id IS DISTINCT FROM (SELECT i.job_order_id FROM public.credit_notes c JOIN public.invoices i ON i.id=c.invoice_id WHERE c.id=NEW.credit_note_id)
  THEN RAISE EXCEPTION 'Settlement credit job mismatch'; END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION private.prevent_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin raise exception '% is append-only',tg_table_name using errcode='42501'; end;
$function$
;
CREATE TRIGGER crm_upgrade_links BEFORE INSERT OR UPDATE ON public.stock_movements FOR EACH ROW EXECUTE FUNCTION private.crm_upgrade_validate_links();
CREATE TRIGGER crm_upgrade_receipt_guard BEFORE INSERT ON public.goods_receipt_items FOR EACH ROW EXECUTE FUNCTION private.crm_upgrade_receipt_guard();
CREATE TRIGGER crm_upgrade_receipt_immutable BEFORE DELETE OR UPDATE ON public.goods_receipt_items FOR EACH ROW EXECUTE FUNCTION private.prevent_mutation();
CREATE TRIGGER crm_upgrade_receipt_totals AFTER INSERT ON public.goods_receipt_items FOR EACH ROW EXECUTE FUNCTION private.crm_upgrade_refresh_receipt_totals();
CREATE TRIGGER stock_movements_immutable BEFORE DELETE OR UPDATE ON public.stock_movements FOR EACH ROW EXECUTE FUNCTION private.prevent_mutation();
